const proseField='Manuscript prose', notesField='Writing outline';
const editableFields=new Set([proseField,notesField,'Section writing stage','Section manuscript source','Writing intention','Next writing action','Active writing idea','Writing goal origin','Writing goal stage']);
const stageInfo={
 connect:{title:'Write the first draft',help:'Choose one idea below and write it as connected prose. You can leave [check] or [reference] and continue; the outline stays beside you.'},
 rewrite:{title:'Rewrite for the reader',help:'Read the section as one piece. Keep wording that works; rewrite unclear sentences and explain the links between ideas.'},
 polish:{title:'Polish the language',help:'Keep the argument and technical terms stable. Refine wording, sentence length and references without strengthening the claims.'}
};
const encode=encodeURIComponent;
const words=text=>String(text||'').trim().split(/\s+/u).filter(Boolean).length;
const asArray=(value,key)=>Array.isArray(value)?value:Array.isArray(value?.[key])?value[key]:[];
const clone=value=>JSON.parse(JSON.stringify(value));
const safeText=value=>typeof value==='string'?value:value==null?'':Array.isArray(value)?value.map(safeText).join('\n'):JSON.stringify(value);

export function hasOwnWritingGoal(fields,moveId,stage){return fields?.['Writing goal origin']==='own'&&fields['Active writing idea']===(moveId||'')&&fields['Writing goal stage']===stage&&!!String(fields['Writing intention']||'').trim();}

export function sectionScaffold(fields){
 if(String(fields?.[proseField]||'').trim())throw new Error('Your section already contains writing. The outline cannot replace it.');
 const scaffold=String(fields?.['Writing scaffold']||'').trim();
 if(!scaffold)throw new Error('This section has no writing scaffold yet. Use the outline to begin in your own words.');
 return scaffold;
}
export function sectionSuggestion(job,suggestion,current){
 const quote=suggestion?.quote,replacement=suggestion?.replacement,original=job?.text;
 if(typeof original!=='string'||typeof quote!=='string'||!quote.trim()||typeof replacement!=='string'||!replacement.trim()||quote===replacement)return {notice:'This suggestion has no exact, usable replacement.'};
 const start=original.indexOf(quote);
 if(start<0||original.indexOf(quote,start+1)>=0)return {notice:'The quoted words are not unique in the reviewed version. Select the intended passage and ask again.'};
 if(job.selected_text&&!job.selected_text.includes(quote))return {notice:'This suggestion is outside the passage you asked the tutor to read.'};
 const now=current.indexOf(quote);
 if(now<0)return {notice:'You have already changed these words. Keep your revision or ask about the current text.'};
 if(current.indexOf(quote,now+1)>=0)return {notice:'These words appear more than once in your draft. Select the intended passage and ask again.'};
 return {text:current.slice(0,now)+replacement+current.slice(now+quote.length),start:now,end:now+replacement.length,notice:current===original?'Apply this wording to your draft only. You can undo it.':'This exact passage is unchanged. Other edits will be kept; check that the suggestion still fits its context.'};
}

// One section owns its revision base and recovery copy. A save never erases edits
// made while that request was in flight, and a conflict stops automatic writes.
export class SectionDraft {
 constructor(note,{cached=null,save,cache=()=>true,status=()=>{}}){
  this.note=clone(note);this.values={...note.fields};this.write=save;this.cache=cache;this.status=status;this.dirty={};this.saving=null;this.error='';
  if(cached?.fields&&typeof cached.fields==='object'){
   for(const [name,value] of Object.entries(cached.fields))if(editableFields.has(name)&&typeof value==='string'){this.values[name]=value;if(value!==(note.fields[name]||''))this.dirty[name]=value;}
   if(Object.keys(this.dirty).length&&cached.base_hash!==note.hash)this.error='A recovered browser draft differs from the current vault version. Compare them before saving.';
  }
  if(note.conflict)this.error='This section has competing saved versions. Compare them before saving.';
 }
 keep(){return this.cache(Object.keys(this.dirty).length?{base_hash:this.note.hash,fields:{...this.dirty}}:null)}
 change(name,value){if(!editableFields.has(name)||typeof value!=='string')throw new Error('This field is not editable in section writing.');this.values[name]=value;if(value!==(this.note.fields[name]||''))this.dirty[name]=value;else delete this.dirty[name];const kept=this.keep();this.status(this.error||(kept?'Draft kept in this browser · saving to Obsidian…':'Browser recovery is unavailable. Keep this screen open until saving succeeds.'),!!this.error||!kept);}
 async save(){
  if(this.saving){await this.saving;return this.error?false:this.save()}
  if(this.error)return false;if(!Object.keys(this.dirty).length)return true;
  const sent={...this.dirty},base=this.note.hash;this.status('Saving to Obsidian…');
  this.saving=(async()=>{
   try{
    const result=await this.write(base,sent);if(result.conflict)throw new Error('Saved versions need comparison. Your current draft is kept.');
    this.note={...this.note,...result,fields:{...this.note.fields,...sent,...result.fields}};
    for(const name of new Set([...Object.keys(sent),...Object.keys(this.dirty)])){if(this.values[name]===(this.note.fields[name]||''))delete this.dirty[name];else this.dirty[name]=this.values[name]||'';}
    this.keep();this.status('Saved in Obsidian · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}));return true;
   }catch(e){this.error=e.message||'The section could not be saved.';this.keep();this.status(this.error,true);return false}
   finally{this.saving=null}
  })();
  const ok=await this.saving;return ok&&Object.keys(this.dirty).length?this.save():ok;
 }
}

