   $('#sw-resource-status').textContent=c.resources.length+' matching passages.'+(result.truncated?' Showing the first '+(result.limit||1000)+'. Narrow your search to find more.':'')+' '+(result.notice||'Tags help you find material; they do not establish approval or source support.');const kindValue=$('#sw-resource-kind').value;if(result.kinds?.length){$('#sw-resource-kind').innerHTML='<option value="">All material</option>'+result.kinds.map(k=>`<option value="${esc(k)}">${esc(({passage:'Earlier manuscript',quotation:'Quotation',wording:'Wording proposal'})[k]||k)}</option>`).join('');$('#sw-resource-kind').value=kindValue;}$('#sw-version-options').innerHTML=(result.versions||[]).map(v=>`<option value="${esc(v)}"></option>`).join('');
   $('#sw-tag-options').innerHTML=(result.tags||[]).map(t=>`<option value="${esc(t)}"></option>`).join('');
